questionvariables.text:
aa:rand_with_step(110,160,5);
bb:aa+20;
cc:bb+25;
dd:rand_with_step(2,6,1);
ee:rand_with_step(50,90,10);
ff:cc-20;
ta1_a:decimalplaces((dd*(ln(num((bb-ee)/(cc-ee)))-ln(denom((bb-ee)/(cc-ee)))))/(ln(num((ff-ee)/(cc-ee)))-ln (denom((ff-ee)/(cc-ee)))),2);
whole_part: floor(ta1_a);
decimal_part:(ta1_a-whole_part)*10;
ta1:if decimal_part<2.5 then whole_part elseif decimal_part<5 then whole_part+0.5 elseif decimal_part<7.5 then whole_part+0.5 else whole_part+1;
ta2_a:decimalplaces((dd*(ln(num((aa-ee)/(cc-ee)))-ln(denom((aa-ee)/(cc-ee)))))/(ln(num((ff-ee)/(cc-ee)))-ln (denom((ff-ee)/(cc-ee)))),2);
whole_part: floor(ta2_a);
decimal_part:(ta2_a-whole_part)*10;
ta2:if decimal_part<2.5 then whole_part elseif decimal_part<5 then whole_part+0.5 elseif decimal_part<7.5 then whole_part+0.5 else whole_part+1;
